#include <stdio.h>

/* 把外面那张牌改成指着 target 那只碗 */
void point_to(int **pp, int *target) {
    *pp = target;
}

int main(void) {
    int fish = {fish};
    int bone = {bone};
    int *p = &fish;

    point_to(&p, &bone);
    printf("牌子换过去了吗：%d\n", p == &bone);
    printf("牌子指着的那只碗里：%d\n", *p);
    return 0;
}
